-- إصلاحُ الملخَّصات المبتورة.
-- وُلِّد آليًّا بـ scripts/repair-truncated-summaries.py: كلُّ حرفٍ مُضافٍ
-- منقولٌ بحرفه من حقل body الخاصِّ بالصفِّ نفسِه، لا من خارجه.
BEGIN;
UPDATE sharia_rulings SET summary = '(1) الزكاة: واجبة بشروطها (النصاب، الحول، الملك التام)، لها مصارف محددة في القرآن ثمانية، ولا تصح لغني أو هاشمي. (2) الصدقة: تطوعية ومستحبة، تشمل المال والعمل الصالح وحتى الابتسامة، لا تشترط نصاباً…'
  WHERE id = '858eded6-7bc5-40b5-99ee-8e2335b1e047';
UPDATE sharia_rulings SET summary = 'ذهب جمهور العلماء إلى عدم جواز الجمع في الحضر إلا لعذر. وأجاز الحنابلة والمالكية الجمع للحاجة الشديدة أو المرض أو المطر. واستدل أصحاب الجواز بحديث ابن عباس: «جمع رسول الله ﷺ بين الظهر والعصر وبين المغرب والعشاء بالمدينة من غير خوف ولا سفر» (مسلم — 705)…'
  WHERE id = '8a660e86-4e40-428f-95c7-5d2e17c4ee44';
UPDATE sharia_rulings SET summary = 'زكاة الفطر (صدقة الفطر) واجبة عند جمهور العلماء على كل مسلم يملك ما يزيد على قوته وقوت عياله ليلة العيد. ومقدارها: صاع من غالب قوت البلد (نحو 2.5-3 كيلو). ووقت إخراجها: من غروب آخر يوم من رمضان إلى قبل صلاة العيد…'
  WHERE id = '8a7d1caa-8c6e-4043-ae5d-dbeb4dcd9bf6';
UPDATE sharia_rulings SET summary = 'الحديث الحسن: ما اتصل سنده برواة عدول ضابطين (لكن ضبطهم أدنى من ضبط رجال الصحيح) مع انتفاء الشذوذ والعلة. والصحيح يتفوق عليه في درجة الضبط فقط. أما الحسن لغيره: فهو ضعيف ارتقى بتعدد طرقه…'
  WHERE id = '8cdf86eb-c128-46f7-ab83-46db48fa587d';
UPDATE sharia_rulings SET summary = 'نصاب الذهب 20 مثقالاً وهو 85 جراماً تقريباً. ونصاب الفضة 200 درهم وهو 595 جراماً تقريباً. وزكاتهما ربع العشر (2.5%). أما العملات الورقية: فتُقاس بنصاب الذهب أو الفضة، وقد رأى كثيرون اليوم الاحتياط بنصاب الفضة لأنه أنفع للفقراء لانخفاض قيمته…'
  WHERE id = '8da59137-00f8-4fab-8307-6c2aadbdb849';
UPDATE sharia_rulings SET summary = 'الطلاق مباح بأصله، قال ابن عمر: ''أبغض الحلال إلى الله الطلاق''. أنواعه: (1) الطلاق السني: في طهر لم يُجامَع فيه. (2) البدعي: في الحيض أو في طهر جامع فيه، ويقع مع الإثم…'
  WHERE id = '8dc0da57-2833-4056-8248-2e202c47083c';
UPDATE sharia_rulings SET summary = 'عند دخول المنزل يُستحب التسمية والسلام على أهله، ومن الدعاء المأثور: «اللهم إني أسألك خير المولج وخير المخرج، بسم الله ولجنا وبسم الله خرجنا وعلى الله ربنا توكلنا»…'
  WHERE id = '90cc627d-5693-4b45-add8-aab72d2b97c0';
UPDATE sharia_rulings SET summary = 'الجرح والتعديل علم يُبيَّن فيه أحوال رواة الحديث من حيث القبول والرد. التعديل: توثيق الراوي وإثبات عدالته وضبطه. الجرح: الحكم بضعفه لخلل في عدالته أو ضبطه. وألفاظ التوثيق تتدرج من «ثقة ثقة» إلى «لا بأس به» وغيرها…'
  WHERE id = '94ec0139-d486-4460-883e-e45a04a14e20';
UPDATE sharia_rulings SET summary = 'الذكر نوعان: (1) ذكر الثناء والتمجيد لله تعالى كالتسبيح والتحميد والتهليل والتكبير، وهذا عبادة مستقلة يُثاب عليها المسلم. (2) دعاء المسألة وهو طلب الحاجات من الله، وهو عبادة أيضاً لقوله ﷺ «الدعاء هو العبادة»…'
  WHERE id = '959cdab3-b51d-458c-8160-fcbb099e6388';
UPDATE sharia_rulings SET summary = 'الإبرة الوريدية (IV) التي تُعطى للتغذية تُفطِّر لأنها تُغني عن الأكل والشرب. أما إبر الدواء (المضادات الحيوية والمسكنات) والتحاليل (سحب الدم) فلا تُفطِّر في الراجح لأنها لا تُغني عن الطعام ولا تصل للجهاز الهضمي…'
  WHERE id = '988c0c88-70bc-41e9-9de8-50c02ed1a4f1';
UPDATE sharia_rulings SET summary = 'يجب الغسل من الجنابة عند إرادة الصلاة، أي يجب التطهر قبل كل صلاة لا مجرد الجنابة. فيجوز للجنب النوم قبل الغسل، والأكل والشرب، والإقامة في البيت. غير أنه يُستحب له الوضوء قبل النوم وقبل الأكل…'
  WHERE id = '9934eda3-d735-4e81-83f3-29ca63bb7422';
UPDATE sharia_rulings SET summary = 'الواجب قول «سبحان ربي الأعلى» مرة، والأفضل ثلاثاً. ومن الأدعية المأثورة: «اللهم اغفر لي ذنبي كله دقّه وجلّه وأوله وآخره وعلانيته وسره» — رواه مسلم. والسجود أقرب ما يكون العبد من ربه.'
  WHERE id = '9b17577e-ba66-4321-9bed-c40a05295824';
UPDATE sharia_rulings SET summary = 'بعد وصول النبي ﷺ إلى المدينة أرسى ثلاث ركائز حضارية: (1) المسجد النبوي — بناه بيده الشريفة وكان مركزاً للصلاة والتعليم والقضاء. (2) المؤاخاة بين المهاجرين والأنصار — جعل بين كل مهاجري وأنصاري أخوة كاملة تشمل التوارث في البداية…'
  WHERE id = '9d78b9b8-033f-4bf8-8c71-7b2e212bb863';
UPDATE sharia_rulings SET summary = 'أكثر الصحابة رواية للحديث: 1) أبو هريرة: 5374 حديثاً — أكثرهم مطلقاً. 2) عبد الله بن عمر: 2630. 3) أنس بن مالك: 2286. 4) السيدة عائشة: 2210. 5) عبد الله بن عباس: 1660…'
  WHERE id = '9e1b8533-1d88-48cf-aa5c-850ffb3830a8';
UPDATE sharia_rulings SET summary = 'لا يصح أذان غير المسلم ولا إمامته بالمسلمين بإجماع الفقهاء، لأن الأذان إعلام وشعيرة إسلامية والإمامة منصب ديني. أما الاستعانة بغير المسلم في الأعمال الدنيوية المجردة من العبادة فجائزة بشروط عدم اتخاذه ولياً وعدم إذلال المسلمين…'
  WHERE id = '9e2aff59-e04a-4106-a387-228dc0677594';
UPDATE sharia_rulings SET summary = 'للعلماء المعاصرين في التصوير الرقمي رأيان بارزان: (1) القائلون بالتحريم المطلق: يرون أن التصوير يدخل في حكم التصوير المحرم في الحديث ''أشد الناس عذاباً المصوِّرون''…'
  WHERE id = '9efe0248-3edf-406c-9741-3e55d3548880';
UPDATE sharia_rulings SET summary = 'زيارة المريض من حقوق المسلم على المسلم، وقد قال النبي صلى الله عليه وسلم: (إن الله يقول يوم القيامة: يا ابن آدم مَرِضتُ فلم تَعُدني...). وللزائر نزهة في خرافة الجنة حتى يرجع…'
  WHERE id = 'a0a706e5-66e7-43f4-ab3f-75e6c2c3f692';
UPDATE sharia_rulings SET summary = 'الدَّين جائز في الإسلام وقد استدان النبي ﷺ. شروطه: 1) النية الصادقة على الوفاء. 2) القدرة المتوقعة على السداد. 3) توثيق الدين بالكتابة عند الإمكان لقوله تعالى: ﴿وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ﴾ [البقرة: ٢٨٢]…'
  WHERE id = 'a1d6e75d-158b-4f0f-aca2-02ae5522dc02';
UPDATE sharia_rulings SET summary = 'صيام يوم عرفة (التاسع من ذي الحجة) سنة مؤكدة لغير الحاج، وفضله أن النبي ﷺ قال «يكفر السنة الماضية والباقية». أما صيام يوم عاشوراء (العاشر من المحرم) فسنة أيضاً وفضله تكفير سنة ماضية، ويستحب صيام يوم قبله أو بعده مخالفة لليهود…'
  WHERE id = 'a28ffd36-532d-4cd4-8064-8eef5b16a1c3';
UPDATE sharia_rulings SET summary = 'التسبيح بالسبحة مسألة خلافية بين العلماء. الجمهور على إباحتها لأن المقصود ضبط العدد، وقد ثبت استخدام النوى والحصى في عد الذكر عن بعض الصحابة. وذهب بعض العلماء كابن تيمية إلى أن العقد بالأنامل أفضل لما جاء في الحديث…'
  WHERE id = 'a807957b-a294-44bb-87ff-6707ad995ccf';
UPDATE sharia_rulings SET summary = 'عاشوراء: اليوم العاشر من المحرم. فضله: قال ﷺ: ''صيام يوم عاشوراء أحتسب على الله أن يكفّر السنة التي قبله'' (مسلم). سبب صيامه: لما قدم النبي ﷺ المدينة وجد اليهود يصومونه قالوا: يوم نجّى الله فيه موسى وأغرق فرعون…'
  WHERE id = 'a8108471-8959-4b5e-b2e4-ddab96295425';
UPDATE sharia_rulings SET summary = 'يوسف بن يعقوب عليهما السلام حدّثه أبوه أن الله اصطفاه. فحسده إخوته وألقوه في الجُبّ ثم بيع عبداً في مصر. وفي مصر راودته سيدته عن نفسه فعصم الله نفسه وسُجن. وفي السجن فسَّر الأحلام، فبلغ أمره الملك فأُطلق وتولّى خزائن الأرض…'
  WHERE id = 'a991eb05-7641-4aaa-a1c7-342b34b078aa';
UPDATE sharia_rulings SET summary = 'أفضل الذكر «لا إله إلا الله» لقوله ﷺ «أفضل الذكر لا إله إلا الله». ومن أجمع الأذكار: (1) «سبحان الله وبحمده، سبحان الله العظيم» —خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن—…'
  WHERE id = 'a9b612e8-f0f8-4cbe-8a2b-e5950e60c514';
UPDATE sharia_rulings SET summary = 'الاستجمار بورق التواليت جائز ويُجزئ عند جمهور العلماء المعاصرين لأن المقصود إزالة النجاسة، وورق التواليت طاهر قادر على الإزالة. وشروط الاستجمار: (1) ألا يقل عن ثلاث مسحات…'
  WHERE id = 'ac90f76d-2236-4b06-9ed6-255158ad0558';
UPDATE sharia_rulings SET summary = 'الصدقة الجارية مشروعة ومستحبة استحباباً مؤكداً، وهي من أفضل الأعمال التي ينتفع بها الإنسان بعد موته. الدليل: قال النبي ﷺ: ''إذا مات الإنسان انقطع عنه عمله إلا من ثلاثة: إلا من صدقة جارية، أو علم يُنتفع به، أو ولد صالح يدعو له'' (رواه مسلم)…'
  WHERE id = 'adf53f83-4b2a-4592-a502-72caff6b9d96';
UPDATE sharia_rulings SET summary = 'المريض الذي يشق عليه الصيام أو يضره مشقة شديدة يجوز له الفطر وجوباً عند الضرر، وكراهة أو جوازاً عند المشقة غير الضارة. وعليه القضاء بعد رمضان متى استطاع دون تأخير مقصود…'
  WHERE id = 'b3fc7d91-da87-48aa-aae4-fecd8e886df8';
UPDATE sharia_rulings SET summary = 'يجب صيام رمضان بخمسة شروط: (1) الإسلام. (2) البلوغ —فلا يجب على غير البالغ وإن استُحب تعويده—. (3) العقل —فلا يجب على المجنون—. (4) القدرة —فيباح الفطر للمريض والمسافر مع القضاء—…'
  WHERE id = 'b472ae3b-ec06-4686-a1b8-e0e4d1fd1ed3';
UPDATE sharia_rulings SET summary = 'اختلف الفقهاء في هذه المسألة على قولين: الأول: الجواز، وهو مذهب الشافعية والحنابلة ورجحه ابن تيمية؛ لأن الأجرة على التعليم والنفع لا على القرآن ذاته. والثاني: الكراهة أو المنع، وهو قول المالكية والحنفية في رواية…'
  WHERE id = 'b5bdfb72-f84c-4dc2-ac55-1e330f6f435b';
UPDATE sharia_rulings SET summary = 'العول في المواريث يعني: زيادة السهام المقررة عن أصل الفريضة بسبب تزاحم الورثة أصحاب الفروض، فيُزاد في أصل المسألة بمقدار الزيادة وتنقص حصة كل وارث بنسبة متساوية…'
  WHERE id = 'b63f4262-c288-45e9-9589-d2d9a47322d2';
UPDATE sharia_rulings SET summary = 'اختلف العلماء على ثلاثة أقوال: (1) الوجوب على المأموم وإن سمع قراءة الإمام — قول الشافعي ورواية عن أحمد، لحديث «لا صلاة لمن لم يقرأ بفاتحة الكتاب». (2) لا تجب على المأموم بل تحمّلها عنه الإمام — قول الحنفية والمالكية…'
  WHERE id = 'b9153ef6-abf3-4f99-8f87-9b9c87193cd2';
COMMIT;
